css:
/* ①背表紙 */
.card{position:relative;background:#fff;border-radius:14px;box-shadow:0 6px 18px rgba(0,0,0,.06)}
.card::before{content:"";position:absolute;left:-10px;top:-6px;bottom:-6px;width:22px;
              border-radius:12px 0 0 12px;background:#6E7FB0;z-index:-1}
/* ②版ズレ／二重輪郭 */
.ph{position:relative;border-radius:50%;overflow:hidden}
.ph-wrap::after{content:'';position:absolute;inset:-14px;border:1px solid #c9ad6a;
                border-radius:50%;translate:-6px 6px;pointer-events:none}
.ghost{position:absolute;inset:0;background:#5f9c52;transform:translate(6px,10px);z-index:-1}
/* ③背景エコー（本体と同じ半径を拡大して敷く） */
.echo{position:absolute;top:-60px;left:-40px;width:460px;height:260px;background:#f3f4f6;
      border-radius:24px 9999px 9999px 24px / 24px 50% 50% 24px;z-index:0}
